// kaltra-outpost entry point. Route table mirrors docs/protocol-v1.md (v1.1) section 4.
// Routes not yet implemented return 501 unknown_route and name themselves.

// `Env` comes from worker-configuration.d.ts (generated by `wrangler types`). Never hand-write it.

import { errorResponse } from "./errors";
import { engineKeys } from "./config";
import { verifyRequest } from "./signature";
import { meta } from "./routes/meta";
import { migrate, query } from "./routes/store";
import { llm } from "./routes/llm";
import { source } from "./routes/source";
import { devDoor } from "./doors/dev";
import { registerDoor, doorModule } from "./doors/registry";
import { doorSend } from "./routes/door-send";
import { doorNotify } from "./routes/door-notify";
import { deliver, type InboundMessage } from "./consumer";
import type { RouteContext } from "./context";
import { cleanup } from "./cron";

type Handler = (req: Request, env: Env, params: Record<string, string>, ctx?: ExecutionContext) => Promise<Response>;

interface Route {
  method: string;
  pattern: RegExp;
  keys: string[];
  handler: Handler;
}

const notImplemented =
  (route: string): Handler =>
  async () =>
    Response.json({ error: { code: "unknown_route", message: `${route} is specified in docs/protocol-v1.md but not implemented yet`, retryable: false } }, { status: 501 });

function route(method: string, path: string, handler: Handler): Route {
  const keys: string[] = [];
  const pattern = new RegExp(
    "^" + path.replace(/<([a-z-]+)>/g, (_, k) => { keys.push(k); return "([^/]+)"; }) + "$",
  );
  return { method, pattern, keys, handler };
}

// Engine authentication for /v1/* routes (protocol section 2): buffer the body, verify digest + signature, then act.
function withEngineAuth(routeTemplate: string, handler: (ctx: RouteContext) => Promise<Response>): Handler {
  return async (req, env, params) => {
    const startedAt = Date.now();
    const body = await req.arrayBuffer();
    const result = await verifyRequest(req, body, { keys: await engineKeys(env.KALTRA_ENGINE_PUBLIC_KEYS), expectedProtocol: env.KALTRA_PROTOCOL });
    if (!result.ok) {
      console.log(JSON.stringify({ event: "auth_failed", route: routeTemplate, reason: result.reason }));
      return errorResponse("unauthorized");
    }
    return handler({ req, env, params, body, auth: { keyId: result.keyId, nonce: result.nonce, protocol: env.KALTRA_PROTOCOL }, route: routeTemplate, startedAt });
  };
}

// One route per kind (protocol v1.1, section 4).
// Engine-initiated routes (/v1/*) sit behind Access service-auth plus the Kaltra signature.
// Platform-facing routes (/door/*) sit outside Access and verify the platform signature.
// Tenant-admin routes (export, wipe) accept a validated Access JWT only, never the engine.
const routes: Route[] = [
  route("GET",  "/v1/meta",                              withEngineAuth("/v1/meta", meta)),
  route("POST", "/v1/llm/<credential>",                  withEngineAuth("/v1/llm", llm)),
  route("POST", "/v1/source/<instance>",                 withEngineAuth("/v1/source", source)),
  route("POST", "/v1/store/query",                       withEngineAuth("/v1/store/query", query)),
  route("POST", "/v1/store/migrate",                     withEngineAuth("/v1/store/migrate", migrate)),
  route("POST", "/v1/store/export",                      notImplemented("store.export (tenant admin)")),
  route("POST", "/v1/store/wipe",                        notImplemented("store.wipe (tenant admin)")),
  route("POST", "/door/<kind>/<instance>",               async (req, env, p, ctx) => doorModule(p.kind)?.inbound(req, env, p.instance, ctx) ?? errorResponse("unknown_route")),
  route("POST", "/door/<kind>/<instance>/<action>",      async (req, env, p, ctx) => doorModule(p.kind)?.routes?.[p.action]?.(req, env, p.instance, ctx) ?? errorResponse("unknown_route")),
  route("POST", "/v1/door/<kind>/<instance>/send",       withEngineAuth("/v1/door/send", doorSend)),
  route("POST", "/v1/door/<kind>/<instance>/notify",     withEngineAuth("/v1/door/notify", doorNotify)),
  route("POST", "/v1/door/<kind>/<instance>/fetch",      notImplemented("door.fetch")),
];

// The doors this build carries. A tenant entry point (src/entry.<tenant>.ts) registers its platform doors, then re-exports this worker.
registerDoor(devDoor);

export default {
  async fetch(req: Request, env: Env, ctx?: ExecutionContext): Promise<Response> {
    const url = new URL(req.url);
    try {
      for (const r of routes) {
        if (r.method !== req.method) continue;
        const m = r.pattern.exec(url.pathname);
        if (!m) continue;
        const params: Record<string, string> = {};
        r.keys.forEach((k, i) => (params[k] = decodeURIComponent(m[i + 1])));
        return await r.handler(req, env, params, ctx);
      }
      return errorResponse("unknown_route");
    } catch (e) {
      // Structured always; never the runtime's HTML page. Message text stays out of the response.
      console.log(JSON.stringify({ event: "unhandled", path: url.pathname, error: e instanceof Error ? `${e.name}: ${e.message}` : String(e) }));
      return errorResponse("internal");
    }
  },

  // Queue consumer (section 8): see src/consumer.ts.
  async queue(batch: MessageBatch<InboundMessage>, env: Env): Promise<void> {
    for (const msg of batch.messages) await deliver(env, msg);
  },

  // Hourly cron (section 7): purge expired o_* rows, conversations, audit past retention; refresh key sets.
  async scheduled(_controller: ScheduledController, env: Env, _ctx: ExecutionContext): Promise<void> {
    await cleanup(env);
  },
} satisfies ExportedHandler<Env, InboundMessage>;
